```rust
pub struct DamageMark {
    pub local_pos: Vec3,    // Position relative to entity center
    pub intensity: f32,     // 0.0 = healed, 1.0 = severe
    pub mark_type: MarkType, // Slash, dent, burn, acid
    pub age: f32,           // Seconds since created (for flash decay)
}

pub enum MarkType {
    Slash,    // Linear — blade weapons
    Dent,     // Circular — blunt weapons
    Burn,     // Radial with glow — thermal
    Acid,     // Irregular — chemical
}

pub const MAX_MARKS_PER_ENTITY: usize = 20;
```

