**In the evolution tick, after thermal diffusion:**

```rust
pub fn apply_material_state(grid: &mut FieldEvolutionGrid, materials: &MaterialLookup) {
    for cell in grid.cells_mut() {
        let temp = cell.temperature;
        let mat = materials.lookup(cell.material_id);

        // Continuous hardness modification based on temperature
        // Hardness drops linearly from 60% of melting point onward
        let softening_onset = mat.melting_point * 0.6;
        if temp > softening_onset {
            let softening = ((temp - softening_onset) / (mat.melting_point - softening_onset)).min(1.0);
            cell.effective_hardness = mat.base_hardness * (1.0 - softening * 0.95);
            // At melting point: hardness is 5% of base — essentially zero
        } else {
            cell.effective_hardness = mat.base_hardness;
        }

        // Freezing: below freeze point, hardness increases but brittleness increases too
        if temp < mat.freeze_point {
            let freeze_factor = ((mat.freeze_point - temp) / mat.freeze_point).min(1.0);
            cell.effective_hardness = mat.base_hardness * (1.0 + freeze_factor * 0.5);
            cell.effective_brittleness = mat.base_brittleness + freeze_factor * 0.8;
            // Frozen things are harder but shatter easier
        }

        // Phase transition: melting
        if temp > mat.melting_point && cell.phase == Phase::Solid {
            cell.phase = Phase::Liquid;
            // Geometry retreats: write a small positive value to the zone damage
            // This makes the SDF surface pull back — the material "melts away"
            grid.zone_sdf_erosion[cell.index] += 0.02; // 2cm of surface retreat per tick while molten
        }

        // Phase transition: boiling
        if temp > mat.boiling_point && cell.phase == Phase::Liquid {
            cell.phase = Phase::Gas;
            // Geometry fully retreats — this cell is now empty space
            grid.zone_sdf_erosion[cell.index] += 0.5;
            cell.opacity = 0.1; // Near-transparent vapor
        }

        // Phase transition: freezing (liquid → solid)
        if temp < mat.freeze_point && cell.phase == Phase::Liquid {
            cell.phase = Phase::Solid;
            // Geometry stops retreating. Surface may even expand slightly (ice expands)
            if mat.expands_on_freeze {
                grid.zone_sdf_erosion[cell.index] -= 0.01;
            }
        }
    }
}
```

