    pub charge: f32,            // Coulombs
    pub stress: f32,            // Pa accumulated
    pub cooling_rate: f32,      // K/s recent average
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Phase { Solid, Liquid, Gas, Plasma }
