impl MaterialCoord {
    pub fn density(&self) -> f32 {
        // e_density is embedding dim 0, encoded as log-scale
        // 0 = air (1.2 kg/m³), 1 = water (1000), 2 = iron (7874), 3 = osmium (22590)
        1.2 * 10f32.powf(self.embedding[0] * 1.45)
    }
    pub fn thermal_conductivity(&self) -> f32 {
        // e_conductivity_thermal is embedding dim 5
        // 0 = insulator (0.02 W/mK), 1 = copper (400 W/mK)
        0.02 * (400.0 / 0.02f32).powf(self.embedding[5])
    }
    pub fn melting_point(&self) -> f32 {
        // e_melting is embedding dim 6
        // 0 = mercury (234K), 0.5 = aluminum (933K), 1 = tungsten (3695K)
        234.0 + self.embedding[6] * (3695.0 - 234.0)
    }
    pub fn viscosity(&self) -> f32 {
        // e_viscosity is embedding dim 7
        self.embedding[7]
    }
    pub fn hardness(&self) -> f32 { self.embedding[1] * 15.0 }
    pub fn roughness(&self) -> f32 { self.embedding[10] }
    pub fn reflectance(&self) -> f32 { self.embedding[9] }
    pub fn opacity(&self) -> f32 { self.embedding[12] }
    pub fn reactivity(&self) -> f32 { self.embedding[14] }
    pub fn is_combustible(&self) -> bool { self.volatile_capacity() > 0.1 }
    pub fn volatile_capacity(&self) -> f32 {
        // Derived from bond_energy (dim 17) and density — organic materials have
        // moderate bond energy and moderate density
        let organic_score = (1.0 - self.embedding[17]) * (1.0 - self.embedding[0].min(1.0));
        organic_score.max(0.0)
    }
    pub fn pyrolysis_temp(&self) -> f32 {
        // Higher bond energy → higher pyrolysis temperature
        400.0 + self.embedding[17] * 600.0  // 400K to 1000K
    }
    // Albedo for the renderer — derived from EM embedding dims
    pub fn albedo(&self) -> Vec3 {
        // This is a simplification. The full projection should be a learned mapping.
        // For now: derive from density, reflectance, oxidation_state, bond_energy
        // Low density + low reflectance = organic (brown/green)
        // High density + high reflectance = metal (gray/silver)
        // Medium density + low reflectance = stone (gray/brown)
        let metallic = self.embedding[8]; // electrical conductivity ≈ metallic
        let organic = self.volatile_capacity();
        if metallic > 0.5 {
            // Metal: gray to silver, brighter with higher reflectance
            let brightness = 0.4 + self.embedding[9] * 0.4;
            Vec3::new(brightness, brightness * 0.97, brightness * 0.95)
        } else if organic > 0.3 {
            // Organic: brown to green
            Vec3::new(0.35 + organic * 0.15, 0.25 + organic * 0.1, 0.12)
        } else {
            // Mineral/stone: gray-brown
            let base = 0.2 + self.embedding[1] * 0.15; // harder stone is lighter
            Vec3::new(base + 0.05, base + 0.03, base)
        }
    }
    pub fn metallic(&self) -> f32 { self.embedding[8].clamp(0.0, 1.0) }
}
