    // Plasma radiates heat to all neighbors (THIS is the positive feedback)
    let radiation_output = cell_temp * 0.15 * dt; // 15% of temperature radiated per lifecycle step
    let per_neighbor = radiation_output / 6.0;
    let neighbors = [
        idx + 1, idx - 1,
        idx + GRID_NX, idx.wrapping_sub(GRID_NX),
        idx + GRID_NX * GRID_NY, idx.wrapping_sub(GRID_NX * GRID_NY),
    ];
    for &nbr in &neighbors {
